<?php
namespace Tests\Feature;
use App\Models\Branch; use App\Models\CostCenter; use App\Models\Department; use App\Models\Employee; use App\Models\Tenant; use Illuminate\Support\Str; use Tests\TestCase;
class OrganizationStructureTest extends TestCase { public function test_employee_can_be_assigned_to_branch_department_and_cost_center():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Org '.Str::random(5)]);try{tenancy()->initialize($tenant);$b=Branch::create(['code'=>'AMM','name'=>'Amman']);$d=Department::create(['code'=>'OPS','name'=>'Operations','branch_id'=>$b->id]);$c=CostCenter::create(['code'=>'OPS-01','name'=>'Operations','department_id'=>$d->id]);$e=Employee::create(['name'=>'Worker','national_id'=>'ORG-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active','branch_id'=>$b->id,'department_id'=>$d->id,'cost_center_id'=>$c->id]);$this->assertSame('AMM',$e->branch->code);$this->assertSame('OPS',$e->department->code);$this->assertSame('OPS-01',$e->costCenter->code);$b->delete();$e->refresh();$this->assertNull($e->branch_id);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
